// Thought inbox — capture endpoint.
//
// Darrell sends text from anywhere while no Claude session is live. n8n
// stores it on disk; the next session that calls /webhook/briefing sees it
// FIRST in the response payload, before anything else.
//
// Accepts JSON body or plain text:
//   POST /webhook/thought
//   { "text": "...", "tags": ["vacation"], "priority": "low" }
//
// Or as plain text body (Content-Type doesn't matter; we coalesce):
//   curl -X POST -d "fix the iOS PWA cache thing" https://.../webhook/thought
//
// Stored at /data/poetech-briefing/inbox/<iso-timestamp>.json with shape:
//   { id, captured_at, text, tags, priority, ack_at: null }
//
// Per AI-FOUNDATION-INTERNAL-OPERATIONS: this is the persistent memory
// bridge between sessions. Future Claude reads thoughts from here, acts on
// them, then POSTs to /webhook/thought/ack with the id to mark done.

const fs = require('fs');
const path = require('path');

const INBOX_DIR = '/data/poetech-briefing/inbox';
try { fs.mkdirSync(INBOX_DIR, { recursive: true }); } catch (_) {}

const input = $input.first().json || {};
const body = input.body && typeof input.body === 'object' ? input.body : input;

// Pull text from JSON `text`, or from a raw body, or from a `data` field.
let text = '';
if (typeof body === 'string') text = body;
else if (typeof body.text === 'string') text = body.text;
else if (typeof body.data === 'string') text = body.data;
else if (input.bodyText) text = String(input.bodyText);
else text = JSON.stringify(body);

text = text.trim();
if (!text) {
  return [{ json: { ok: false, error: 'empty thought; provide JSON { text: "..." } or POST raw text' } }];
}

const tags = Array.isArray(body.tags) ? body.tags.map(String) : [];
const priority = (body.priority || 'normal').toString();

const capturedAt = new Date().toISOString();
const id = 'th-' + capturedAt.replace(/[:.]/g, '-') + '-' + Math.floor(Math.random() * 10000);
const record = { id, captured_at: capturedAt, text, tags, priority, ack_at: null };

const safeFn = id + '.json';
try {
  fs.writeFileSync(path.join(INBOX_DIR, safeFn), JSON.stringify(record, null, 2));
} catch (e) {
  return [{ json: { ok: false, error: 'failed to write: ' + String(e) } }];
}

return [{ json: { ok: true, id, captured_at: capturedAt, queued_for_next_session: true } }];

// Thought-ack endpoint — a Claude session marks a thought as 'read' after
// it has incorporated the thought into a brief/action.
//
// POST /webhook/thought-ack  body: { id: 'th-...', note: 'shipped X' }

const fs = require('fs');
const path = require('path');

const INBOX_DIR = '/data/poetech-briefing/inbox';
const input = $input.first().json || {};
const body = input.body && typeof input.body === 'object' ? input.body : input;
const id = (body.id || '').toString();
const note = (body.note || '').toString();
if (!id) return [{ json: { ok: false, error: 'id required' } }];

const p = path.join(INBOX_DIR, id + '.json');
let rec;
try { rec = JSON.parse(fs.readFileSync(p, 'utf8')); } catch (_) {
  return [{ json: { ok: false, error: 'thought not found: ' + id } }];
}
rec.ack_at = new Date().toISOString();
if (note) rec.ack_note = note;
try { fs.writeFileSync(p, JSON.stringify(rec, null, 2)); }
catch (e) { return [{ json: { ok: false, error: 'write failed: ' + String(e) } }]; }
return [{ json: { ok: true, id, ack_at: rec.ack_at } }];
